script:
(function () {
  'use strict';
  // ---- Tax rule (2026) --------------------------------------------------------------------
  // Additional tax on early distributions from a nonqualified annuity: 10% of the taxable part
  // (the gain) when taken before age 59 1/2. Source: IRC section 72(q); IRS Publication 575
  // (for 2025 returns), "Tax on Early Distributions". Treated here as applying when the
  // withdrawal age is 59 or lower.
  var EARLY_TAX = 0.10;
  var EARLY_AGE = 59.5;
  // -----------------------------------------------------------------------------------------
  // Variable annuity vs. a low-cost taxable account, compounded annually. The starting deposit
  // and each yearly addition go in at the start of the year (both in year 1).
  // Annuity: each year value = value x (1 + gross return) - value x (M&E + admin + fund expenses
  //   + rider fees); the fees are charged on the start-of-year value. Cash-out at the end of
  //   contract year k: surrender charge = schedule[k-1] x value; the gain over deposits is taxed
  //   at the ordinary withdrawal rate, plus the 10% additional tax if under 59 1/2.
  // Taxable account: value x (gross return - fund expense); the set share of each year's positive
  //   return is paid out as dividends/distributions, taxed that year at the distribution rate
  //   and reinvested (raising the cost basis); the remaining gain is taxed at the capital gains
  //   rate on the final sale.
  // Verified (Node, scratch tests): $100,000 at 7% with 2.2% total annuity charges for 15 years
  // = 100,000 x 1.048^15 = $202,031.57; with no fees and no taxes both accounts equal
  // 100,000 x 1.07^15 = $275,903.15; taxable account with 100% paid out yearly at a 20% rate and
  // no fund fee grows at 5.6%: 100,000 x 1.056^15 = $226,442.93 with nothing more owed;
  // with 0% paid out and 15% capital gains: 275,903.15 - 175,903.15 x 0.15 = $249,517.68.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  // --- calc start
  function parseSchedule(text) {
    var t = String(text || '').trim();
    if (t === '') return [];
    var parts = t.split(/[\s,;]+/).filter(function (x) { return x !== ''; }), out = [];
    for (var i = 0; i < parts.length; i++) {
      var v = parseFloat(parts[i].replace('%', ''));
      if (isNaN(v) || v < 0 || v > 25 || !/^-?\d*\.?\d+%?$/.test(parts[i])) return null;
      out.push(v / 100);
    }
    return out.length > 30 ? null : out;
  }

  function project(p) {
    var va = 0, basis = 0, vaFees = 0, tx = 0, txBasis = 0, txFees = 0, txTax = 0, rows = [];
    var charge = p.me + p.admin + p.fund + p.rider;
    for (var k = 1; k <= p.years; k++) {
      var add = (k === 1 ? p.start : 0) + p.contrib;
      va += add; basis += add; tx += add; txBasis += add;
      var fee = va * charge;
      vaFees += fee;
      va = Math.max(0, va * (1 + p.rate) - fee);
      var txFee = tx * p.txFee, growth = tx * p.rate - txFee;
      txFees += txFee;
      var paidOut = Math.max(0, growth) * p.payout, taxNow = paidOut * p.divTax;
      tx = Math.max(0, tx + growth - taxNow);
      txBasis += paidOut - taxNow;
      txTax += taxNow;
      var age = p.age + k, sc = (k <= p.schedule.length ? p.schedule[k - 1] : 0) * va;
      var gain = Math.max(0, va - sc - basis);
      var vaTax = gain * p.ordTax, pen = age < EARLY_AGE ? gain * EARLY_TAX : 0;
      var txGain = Math.max(0, tx - txBasis), cg = txGain * p.cgTax;
      rows.push({ year: k, age: age, va: va, basis: basis, vaFees: vaFees, charge: sc, vaTax: vaTax, penalty: pen,
                  vaNet: va - sc - vaTax - pen, tx: tx, txFees: txFees, txTax: txTax + cg, txNet: tx - cg });
    }
    return rows;
  }
  // --- calc end

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function setText(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var p = { start: num('vaStart'), contrib: num('vaContrib'), age: Math.round(num('vaAge')), wAge: Math.round(num('vaWithdrawAge')),
              rate: num('vaReturn'), me: num('vaMe'), admin: num('vaAdmin'), fund: num('vaFund'), rider: num('vaRider'),
              txFee: num('vaTxFee'), payout: num('vaPayout'), ordTax: num('vaOrdTax'), divTax: num('vaDivTax'), cgTax: num('vaCgTax') };
    var schedule = parseSchedule(document.getElementById('vaSchedule').value);
    var error = document.getElementById('vaError');
    var msg = '';
    var keys = ['start', 'contrib', 'age', 'wAge', 'rate', 'me', 'admin', 'fund', 'rider', 'txFee', 'payout', 'ordTax', 'divTax', 'cgTax'];
    if (keys.some(function (k) { return isNaN(p[k]); }) || p.start < 0 || p.contrib < 0 || p.start + p.contrib <= 0)
      msg = 'Enter a starting deposit or yearly addition and fill in every field.';
    else if (p.age < 0 || p.age > 100 || p.wAge <= p.age || p.wAge > 110 || p.wAge - p.age > 70)
      msg = 'The withdrawal age must be after your current age (and no more than 70 years away).';
    else if (p.rate < -50 || p.rate > 50) msg = 'Enter an annual return from -50% to 50%.';
    else if ([p.me, p.admin, p.fund, p.rider, p.txFee].some(function (r) { return r < 0 || r > 10; })) msg = 'Enter each fee from 0% to 10% a year.';
    else if ([p.payout, p.ordTax, p.divTax, p.cgTax].some(function (r) { return r < 0 || r > 100; })) msg = 'Enter tax rates and the paid-out share from 0% to 100%.';
    else if (schedule === null) msg = 'Enter the surrender charges as percentages from 0 to 25 separated by commas, e.g. 7, 6, 5, 4, 3, 2, 1.';
    error.hidden = msg === '';
    if (msg) { error.textContent = msg; return; }
    ['rate', 'me', 'admin', 'fund', 'rider', 'txFee', 'payout', 'ordTax', 'divTax', 'cgTax'].forEach(function (k) { p[k] /= 100; });
    p.years = p.wAge - p.age;
    p.schedule = schedule;
    var rows = project(p), last = rows[rows.length - 1];
    var diff = last.vaNet - last.txNet;
    setText('vaNet', money.format(last.vaNet));
    setText('vaTxNet', money.format(last.txNet));
    setText('vaDiff', (diff < 0 ? '−' : '+') + money.format(Math.abs(diff)));
    setText('vaValue', money.format(last.va));
    setText('vaTotalCharge', ((p.me + p.admin + p.fund + p.rider) * 100).toFixed(2) + '% a year');
    setText('vaFees', money.format(last.vaFees));
    setText('vaCharge', money.format(last.charge));
    setText('vaTax', money.format(last.vaTax + last.penalty));
    setText('vaTxValue', money.format(last.tx));
    setText('vaTxFees', money.format(last.txFees));
    setText('vaTxTax', money.format(last.txTax));
    setText('vaDeposits', money.format(last.basis));
    var ahead = null;
    for (var i = rows.length - 1; i >= 0 && rows[i].vaNet >= rows[i].txNet; i--) ahead = rows[i];
    setText('vaVerdict', ahead === null ? 'With these figures, the annuity cashed out after tax is still behind the taxable account at the withdrawal age.' :
      'With these figures, the annuity cashed out after tax matches or beats the taxable account from the end of year ' +
      ahead.year + ' (age ' + ahead.age + ') onward.');
    document.getElementById('vaEarly').hidden = p.wAge >= EARLY_AGE;
    document.getElementById('vaSchedTable').innerHTML = rows.map(function (r) {
      return '<tr><td>' + r.year + '</td><td>' + r.age + '</td><td>' + money.format(r.va) + '</td><td>' + money.format(r.vaFees) +
        '</td><td>' + money.format(r.vaNet) + '</td><td>' + money.format(r.tx) + '</td><td>' + money.format(r.txNet) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('vaForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
